use vstd::prelude::*;

verus! {

    // Copy a slice of length `len` from `src` starting at `s_start` into
    // `dest` starting at `d_start`, producing a new Vec `result`.
    //
    // Preconditions:
    //   0 ≤ s_start + len ≤ src.len()
    //   0 ≤ d_start + len ≤ dest.len()
    //
    // Postconditions:
    //   result.len() == dest.len()
    //   For every index i < dest.len():
    //     if d_start ≤ i < d_start + len then
    //       result[i] == src[s_start + (i - d_start)]
    //     else
    //       result[i] == dest[i]
    fn copy(src: &Vec<i32>,
            s_start: usize,
            dest: &Vec<i32>,
            d_start: usize,
            len: usize)
            -> (result: Vec<i32>)
        requires
            s_start + len <= src.len(),
            d_start + len <= dest.len(),
        ensures
            result.len() == dest.len(),
            forall<usize>(|i| i < dest.len() ==>
                if i >= d_start && i < d_start + len {
                    result[i] == src[s_start + (i - d_start)]
                } else {
                    result[i] == dest[i]
                }
            ),
    {
        // Start by cloning the whole destination array.
        let mut result = dest.clone();

        // We'll copy element‐by‐element.
        let mut i: usize = 0;
        while i < len
            invariant
                // progress measure
                i <= len,
                // length never changes
                result.len() == dest.len(),
                // for all positions j, the parts of `result` are as expected:
                //   • j < d_start: unchanged
                //   • d_start ≤ j < d_start + i: already copied from src
                //   • j ≥ d_start + i: still original from dest
                forall<usize>(|j| j < dest.len() ==>
                    if j < d_start {
                        result[j] == dest[j]
                    } else if j >= d_start + i {
                        result[j] == dest[j]
                    } else {
                        // d_start ≤ j < d_start + i
                        result[j] == src[s_start + (j - d_start)]
                    }
                ),
            decreases len - i,
        {
            // compute the concrete indices
            let src_idx = s_start + i;
            let dst_idx = d_start + i;

            // proof of in‐bounds
            assert(src_idx < src.len());
            assert(dst_idx < result.len());

            // perform the copy
            result[dst_idx] = src[src_idx];
            i = i + 1;
        }

        result
    }

} // verus

